function applyWidgets(){const defaults={week:true,priorities:true,habits:true,rankings:true,northstar:true,next:true,quote:true,quick:true};if(settings.religion==='islam')defaults.deen=true;let chosen={...defaults,...JSON.parse(localStorage.getItem('personalOsWidgets')||'{}')};if(settings.religion!=='islam')delete chosen.deen;Object.entries(chosen).forEach(([k,v])=>{const el=$(`[data-widget="${k}"]`);if(el)el.classList.toggle('hidden-widget',!v)});$('#widgetToggles').innerHTML=Object.entries(defaults).map(([k,v])=>`<label class="widget-toggle">${({week:'Weekly focus chart',priorities:'Today’s priorities',habits:'Daily rituals',deen:'Deen & Qur’an summary',northstar:'North star',next:'Next learning step',quote:'Daily reminder',quick:'Quick capture',rankings:'Monthly rankings'})[k]}<input type="checkbox" data-widget-toggle="${k}" ${chosen[k]?'checked':''}></label>`).join('');$$('[data-widget-toggle]').forEach(c=>c.onchange=()=>{chosen[c.dataset.widgetToggle]=c.checked;localStorage.setItem('personalOsWidgets',JSON.stringify(chosen));applyWidgets()});}
