async function renderLeaderboard(){
 const host=$('#leaderboardPodium'),full=$('#leaderboardFullList');
 if(!host)return;
 try{
  const data=await api('/leaderboard');leaderboardData=data;
  const monthLabel=new Date(data.month+'-01T12:00:00').toLocaleDateString('en-US',{month:'long',year:'numeric'}).toUpperCase();
  if($('#leaderboardMonth'))$('#leaderboardMonth').textContent=monthLabel;
  if($('#rankingsTitle'))$('#rankingsTitle').textContent=monthLabel+' rankings';
  const top=data.top||[];
  host.innerHTML=top.length?top.slice(0,3).map((x,i)=>'<div class="leaderboard-podium-row '+(x.isYou?'is-you':'')+'"><span class="leaderboard-place">'+['🥇','🥈','🥉'][i]+'</span><span class="leaderboard-person"><b>'+esc(x.display)+'</b><small>#'+x.rank+'</small></span><strong>'+Number(x.xp).toLocaleString()+' XP</strong></div>').join(''):'<div class="empty">The season has started. Earn XP to claim the first place.</div>';
  const mine=data.mine||{rank:null,xp:0,totalXp:0,public:true};
  const yourLine=mine.public?(mine.rank?'Your position · #'+mine.rank:'You have not earned a rank yet'):'You are hidden from public rankings.';
  const yourHtml='<span>'+yourLine+'</span><b>'+Number(mine.xp||0).toLocaleString()+' XP this month</b>';
  if($('#leaderboardYou'))$('#leaderboardYou').innerHTML=yourHtml;
  if($('#leaderboardFullYou'))$('#leaderboardFullYou').innerHTML=yourHtml+' <span class="leaderboard-lifetime">· '+Number(mine.totalXp||0).toLocaleString()+' lifetime XP</span>';
  if(full)full.innerHTML=top.length?top.map(x=>'<div class="leaderboard-full-row '+(x.isYou?'is-you':'')+'"><span class="leaderboard-rank">#'+x.rank+'</span><b>'+esc(x.display)+'</b><strong>'+Number(x.xp).toLocaleString()+' XP</strong></div>').join(''):'<div class="empty">No points have been earned this month yet.</div>';
  const champs=data.champions||[];
  if($('#leaderboardChampions'))$('#leaderboardChampions').innerHTML=champs.length?champs.map(x=>'<div class="champion-row"><span>🏆</span><b>'+new Date(x.month+'-01T12:00:00').toLocaleDateString('en-US',{month:'long',year:'numeric'})+'</b><span>'+esc(x.winner?.display||'—')+'</span><strong>'+Number(x.winner?.xp||0).toLocaleString()+' XP</strong></div>').join(''):'<p class="subtle-count">The first champion will be recorded when this month ends.</p>';
 }catch(error){
  console.warn('Leaderboard unavailable:',error.message);
  host.innerHTML='<p class="subtle-count">Rankings are temporarily unavailable.</p>';
  if(full)full.innerHTML='<p class="subtle-count">Rankings are temporarily unavailable.</p>';
  if($('#leaderboardYou'))$('#leaderboardYou').textContent='Your monthly position will appear here.';
 }
}
function renderOverview(){api('/overview').then(o=>{const pct=o.moduleTotal?Math.round(o.completed/o.moduleTotal*100):0;$('#todayMinutes').textContent=o.todayMin;$('#targetLabel').textContent=`of ${o.dailyTarget} min intention`;$('#todayProgress').style.width=Math.min(100,o.todayMin/o.dailyTarget*100)+'%';$('#weekMinutes').textContent=o.weekMin;$('#weekHours').textContent=(o.weekMin/60).toFixed(1)+' hrs';$('#learningPercent').textContent=pct;$('#learningLabel').textContent=`${o.completed} of ${o.moduleTotal} checkpoints` ;$('#learningProgress').style.width=pct+'%';$('#streak').textContent=o.streak;if($('#learningPctLarge'))$('#learningPctLarge').textContent=pct+'%';$('#ringPct').textContent=pct+'%';$('#learningRing').style.background=`conic-gradient(var(--goal) ${pct*3.6}deg,#343943 0)`;$('#weekTotal').textContent=`${o.weekMin} MINUTES LOGGED`;
const days=[];for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;days.push({key,label:d.toLocaleDateString('en-US',{weekday:'short'}).toUpperCase(),min:o.sessions.find(s=>s.session_date===key)?.minutes||0})}const max=Math.max(60,...days.map(d=>d.min));$('#weekChart').innerHTML=days.map(d=>`<div class="week-day ${d.key===today()?'today':''}"><span class="bar-value">${d.min||''}</span><div class="bar-track"><div class="bar-fill" style="height:${d.min/max*100}%"></div></div><span class="bar-label">${d.label}</span></div>`).join('');const open=tasks.filter(t=>!t.done).slice(0,5);$('#todayTasks').innerHTML=open.length?open.map(t=>`<div class="priority-row"><input class="check" type="checkbox" data-task-check="${t.id}"><div class="priority-copy"><strong>${esc(t.title)}</strong><small>${esc(t.category)}${t.due_date?' · '+localDate(t.due_date):''}</small></div><span class="priority-tag">${esc(t.category)}</span></div>`).join(''):'<div class="empty">No open priorities. Give yourself some breathing room.</div>';$$('[data-task-check]').forEach(c=>c.onchange=()=>toggleTask(c.dataset.taskCheck,c.checked));const next=learningPaths.flatMap(p=>p.lessons||[]).find(l=>l.status!=='Completed');$('#nextModuleTitle').textContent=next?.title||'Your next chapter';}).catch(console.error)}
function renderTasks(){const list=tasks.filter(t=>filter==='all'||(filter==='open'&&!t.done)||(filter==='done'&&t.done));$('#taskCount').textContent=`${list.length} ${list.length===1?'ITEM':'ITEMS'}`;$('#taskList').innerHTML=list.length?list.map(t=>`<article class="task-row ${t.done?'done':''}"><input class="check" type="checkbox" data-task-check="${t.id}" ${t.done?'checked':''}><div class="task-copy"><strong>${esc(t.title)}</strong>${t.detail?`<p>${esc(t.detail)}</p>`:''}</div><span class="task-pill">${esc(t.category)}</span>${t.due_date?`<small class="subtle-count">${localDate(t.due_date)}</small>`:''}<button class="delete-btn" data-delete-task="${t.id}" title="Delete task">×</button></article>`).join(''):'<div class="empty">Nothing here yet. Add one meaningful next action.</div>';$$('[data-task-check]').forEach(c=>c.onchange=()=>toggleTask(c.dataset.taskCheck,c.checked));$$('[data-delete-task]').forEach(b=>b.onclick=()=>deleteTask(b.dataset.deleteTask));}
