const backdrop=$('#modalBackdrop'),form=$('#modalForm');function modal(kicker,title,html,submit){$('#modalKicker').textContent=kicker;$('#modalTitle').textContent=title;form.innerHTML=html;backdrop.classList.add('open');form.onsubmit=submit;const first=form.querySelector('input,textarea');setTimeout(()=>first?.focus(),60)}function closeModal(){backdrop.classList.remove('open');form.onsubmit=null}$('#closeModal').onclick=closeModal;backdrop.onclick=e=>{if(e.target===backdrop)closeModal()};document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();$('#searchBackdrop').classList.remove('open')}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}});
function actions(){return `<div class="form-actions"><button type="button" class="btn-cancel" id="cancelModal">Cancel</button><button class="btn-primary">Save <span>→</span></button></div>`}function bindCancel(){$('#cancelModal').onclick=closeModal}
