function openNote(id){editingNote=notes.find(n=>n.id===id)||null;modal('PERSONAL LIBRARY',editingNote?'Edit your entry':'Capture a thought',`<label>TITLE<input name="title" required value="${esc(editingNote?.title||'')}" placeholder="Give the thought a name"></label><label>YOUR THOUGHT<textarea name="body" rows="8" placeholder="Capture a concept, question, lesson or idea…">${esc(editingNote?.body||'')}</textarea></label><div class="form-actions">${editingNote?'<button type="button" class="btn-cancel" id="deleteNote">Delete</button>':''}<button type="button" class="btn-cancel" id="cancelModal">Cancel</button><button class="btn-primary">Save entry <span>→</span></button></div>`,async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(form));if(editingNote)await api('/notes/'+editingNote.id,{method:'PUT',body:JSON.stringify(d)});else await api('/notes',{method:'POST',body:JSON.stringify(d)});notes=await api('/notes');renderNotes();closeModal();toast('Saved to your library.')});bindCancel();if(editingNote)$('#deleteNote').onclick=async()=>{if(confirm('Delete this entry?')){await api('/notes/'+editingNote.id,{method:'DELETE'});notes=await api('/notes');renderNotes();closeModal();toast('Entry deleted.')}}}
