$('#profileForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.username=(d.username||'').trim().replace(/^@/,'');if(d.username&&!/^[A-Za-z0-9_]{3,24}$/.test(d.username)){toast('Username must be 3–24 letters, numbers or underscores.');return}d.leaderboard_name=(d.leaderboard_name||'').trim().slice(0,24);d.leaderboard_public=$('#leaderboardPublicInput').checked?'1':'0';const previousReligion=settings.religion;settings=await api('/settings',{method:'PATCH',body:JSON.stringify(d)});const {error}=await supabaseClient.auth.updateUser({data:{full_name:d.display_name,username:d.username}});if(error)console.warn('Profile metadata sync:',error.message);$('#northStarText').textContent=settings.north_star;applyReligionVisibility();applyWidgets();if(settings.religion==='islam'||isAdmin)renderDeen();if(settings.religion==='christianity'||isAdmin)renderFaith();if(previousReligion!==settings.religion)switchPage(settings.religion==='islam'?'deen':settings.religion==='christianity'?'faith':'home');renderCalendar();updateClock();toast('Your residence, your rules.')};
async function exportWorkspace(){try{const {data:{session}}=await supabaseClient.auth.getSession();if(!session)throw new Error('Sign in again before exporting your workspace.');const response=await fetch('/api/export',{headers:{Authorization:`Bearer ${session.access_token}`}});if(!response.ok){let detail={};try{detail=await response.json()}catch{}throw new Error(detail.error||'Your backup could not be exported.')}const blob=await response.blob();const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='personal-os-backup.json';document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);toast('Your complete backup has been downloaded.')}catch(error){toast(error.message||'Your backup could not be exported.')}}$('#exportBtn').onclick=$('#settingsExport').onclick=exportWorkspace;
$('#settingsImport').onclick=()=>$('#backupImportFile').click();
$('#backupImportFile').onchange=async event=>{const file=event.target.files?.[0];if(!file)return;try{if(file.size>10*1024*1024)throw new Error('Backup files must be 10 MB or smaller.');if(!confirm('Import this backup and replace the records in your current workspace? Export your current data first if you want to keep it.'))return;const backup=JSON.parse(await file.text());const result=await api('/import',{method:'POST',body:JSON.stringify(backup)});toast(`Imported ${result.imported} records. Refreshing your workspace…`);setTimeout(()=>location.reload(),700)}catch(error){toast(error.message||'The backup could not be imported.')}finally{event.target.value=''}};
const presets=$$('.timer-presets button');function setTimer(min){pauseTimer();timer.duration=min*60;timer.left=timer.duration;presets.forEach(b=>b.classList.toggle('selected',Number(b.dataset.minutes)===min));drawTimer()};function drawTimer(){const m=Math.floor(timer.left/60),s=timer.left%60;$('#timerClock').textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;const p=timer.duration?1-timer.left/timer.duration:0;$('#timerProgress').style.background=`conic-gradient(var(--focus) ${p*360}deg,#252a32 ${p*360}deg)`;$('#timerState').textContent=timer.running?'IN SESSION':timer.left===0?'SESSION COMPLETE':'READY WHEN YOU ARE';$('#timerStart').innerHTML=timer.running?'Pause session <span>Ⅱ</span>':'Begin session <span>→</span>'};function pauseTimer(){timer.running=false;clearInterval(timer.interval);timer.interval=null;drawTimer()}function startTimer(){if(timer.running){pauseTimer();return}if(!$('#timerFocus').value.trim()){$('#timerFocus').focus();toast('Give this session a focus first.');return}timer.running=true;drawTimer();timer.interval=setInterval(async()=>{timer.left--;drawTimer();if(timer.left<=0){pauseTimer();await saveTimedSession(timer.duration/60);toast('Session complete. Your focus time is recorded.');try{new AudioContext().resume().then(()=>{}); }catch{} }},1000)}async function saveTimedSession(min){const focus=$('#timerFocus').value.trim();await api('/sessions',{method:'POST',body:JSON.stringify({session_date:today(),minutes:Math.round(min),focus,reflection:'Completed a timed focus session.'})});sessions=await api('/sessions');renderSessions();renderOverview();renderLeaderboard()}$('#timerStart').onclick=startTimer;$('#timerReset').onclick=()=>{setTimer(50);toast('Timer reset.')};presets.forEach(b=>b.onclick=()=>setTimer(Number(b.dataset.minutes)));$('#beginFocus').onclick=()=>switchPage('focus');setTimer(50);
function openSearch(){$('#searchBackdrop').classList.add('open');$('#globalSearch').value='';$('#searchResults').innerHTML='<p>Search across your tasks, notes and learning path.</p>';setTimeout(()=>$('#globalSearch').focus(),50)}$('#searchOpen').onclick=openSearch;$('#searchBackdrop').onclick=e=>{if(e.target===$('#searchBackdrop'))$('#searchBackdrop').classList.remove('open')};$('#globalSearch').oninput=()=>{const q=$('#globalSearch').value.toLowerCase().trim();if(!q){$('#searchResults').innerHTML='<p>Start typing to search your residence.</p>';return}const hits=[...tasks.filter(t=>(t.title+' '+t.detail).toLowerCase().includes(q)).map(t=>({title:t.title,type:'TASK',page:'tasks'})),...notes.filter(n=>(n.title+' '+n.body).toLowerCase().includes(q)).map(n=>({title:n.title,type:'NOTE',page:'library'})),...modules.filter(m=>m.title.toLowerCase().includes(q)).map(m=>({title:m.title,type:'LEARNING',page:'learning'})),...goals.filter(g=>g.title.toLowerCase().includes(q)).map(g=>({title:g.title,type:'GOAL',page:'goals'})),...quranLogs.filter(x=>(x.surah+' '+x.activity+' '+x.reflection).toLowerCase().includes(q)).map(x=>({title:x.surah,type:'QUR’AN',page:'deen'}))];$('#searchResults').innerHTML=hits.length?hits.slice(0,12).map(h=>`<button class="search-result" data-result-page="${h.page}"><span>↗</span>${esc(h.title)}<small>${h.type}</small></button>`).join(''):'<p>No matching entries in your residence.</p>';$$('[data-result-page]').forEach(b=>b.onclick=()=>{$('#searchBackdrop').classList.remove('open');switchPage(b.dataset.resultPage)})};
function setAuthView(view){const signup=view==='signup';$('#loginForm').classList.toggle('hidden',signup);$('#signupForm').classList.toggle('hidden',!signup);$$('[data-auth-view]').forEach(b=>b.classList.toggle('active',b.dataset.authView===view));$('#authTitle').innerHTML=signup?'Create your <em>account.</em>':'Welcome <em>back.</em>';$('.auth-card>p').textContent=signup?'Create your identity for your personal workspace.':'Sign in to enter your private workspace.';$('#authMessage').textContent='';$('#signupMessage').textContent='Create your account to begin.';}
$$('[data-auth-view]').forEach(b=>b.addEventListener('click',()=>setAuthView(b.dataset.authView)));
$('#signupForm').addEventListener('submit',async event=>{event.preventDefault();const button=event.currentTarget.querySelector('button');const message=$('#signupMessage');const name=$('#signupName').value.trim(),username=$('#signupUsername').value.trim().replace(/^@/,''),email=$('#signupEmail').value.trim(),password=$('#signupPassword').value,religion=$('#signupReligion').value;if(!/^[A-Za-z0-9_]{3,24}$/.test(username)){message.textContent='Username must be 3–24 letters, numbers or underscores.';return}button.disabled=true;button.textContent='Creating your account…';message.textContent='';if(!religion){button.disabled=false;button.innerHTML='Create your account <span>→</span>';message.textContent='Choose an option to personalise your workspace.';return}const {data,error}=await supabaseClient.auth.signUp({email,password,options:{data:{full_name:name,username,religion},emailRedirectTo:AUTH_REDIRECT_URL}});button.disabled=false;button.innerHTML='Create your account <span>→</span>';if(error){message.textContent=error.message;return}if(data.session){await enterWorkspace(data.session)}else{message.textContent='Your account has been created. Check your email to confirm your address, then sign in.';$('#loginEmail').value=email;setAuthView('login');$('#authMessage').textContent='Check your inbox for the confirmation link, then sign in here.';}});
async function enterWorkspace(session){
  const message=$('#authMessage');
  const welcomeMessages=[['Welcome back.','Restoring your personal environment…'],['Your workspace is waking up.','Bringing your plans and progress back into focus…'],['Picking up where you left off.','Syncing your latest activity…'],['Good to have you back.','Preparing your next step…'],['Your progress is right where you left it.','Loading your private residence…']];
  const welcome=welcomeMessages[Math.floor(Math.random()*welcomeMessages.length)];
  $('#welcomeLoaderTitle').textContent=welcome[0];$('#welcomeLoaderMessage').textContent=welcome[1];$('#welcomeLoader').classList.remove('hidden');
  const welcomeStarted=Date.now();
  try {
    const response=await fetch('/api/session',{headers:{Authorization:`Bearer ${session.access_token}`}});
    const result=await response.json();
    if(!response.ok) throw new Error(result.error||'Access denied.');
    authUser=session.user||result.user;isAdmin=result.role==='admin';$('#adminNav').classList.toggle('hidden',!isAdmin);document.body.classList.toggle('is-admin',isAdmin);
    document.body.classList.remove('auth-locked');
    $('#authGate').classList.add('hidden');
    await load();
    api('/login-event',{method:'POST',body:'{}'}).catch(()=>{});
    api('/welcome',{method:'POST',body:'{}'}).catch(()=>{});
    await new Promise(resolve=>setTimeout(resolve,Math.max(0,1400-(Date.now()-welcomeStarted))));
    $('#welcomeLoader').classList.add('hidden');
    if(signupConfirmationPending){toast('Email confirmed — thank you for joining Amstreem. Your residence is ready.');history.replaceState(null,'',window.location.pathname+window.location.search);}
  } catch(error) {
    $('#welcomeLoader').classList.add('hidden');
    await supabaseClient.auth.signOut();
    if(message) message.textContent=error.message;
  }
}
$('#loginForm').addEventListener('submit',async event=>{
  event.preventDefault();
  const button=event.currentTarget.querySelector('button');
  const message=$('#authMessage');button.disabled=true;button.textContent='Signing in…';message.textContent='';
  const {data,error}=await supabaseClient.auth.signInWithPassword({email:$('#loginEmail').value.trim(),password:$('#loginPassword').value});
  button.disabled=false;button.innerHTML='Enter your residence <span>→</span>';
  if(error){message.textContent=error.message;return;}
  await enterWorkspace(data.session);
});
function renderAdminUsers(){const body=$('#adminUserRows'),filter=$('#adminMailFilter')?.value||'new';const visible=adminUsers.filter(u=>filter==='all'||(filter==='sent'?u.thank_you_status==='sent':u.thank_you_status!=='sent'&&u.thank_you_status!=='pending'));$('#adminNewMailCount').textContent=adminUsers.filter(u=>u.email&&u.thank_you_status!=='sent'&&u.thank_you_status!=='pending').length;$('#adminSentMailCount').textContent=adminUsers.filter(u=>u.thank_you_status==='sent').length;body.innerHTML=visible.length?visible.map(u=>{const sent=u.thank_you_status==='sent';const status=sent?'Sent'+(u.thank_you_sent_at?' · '+new Date(u.thank_you_sent_at).toLocaleDateString():''):(u.thank_you_status==='pending'?'Sending / verify':'Not sent');return '<tr><td><input type="checkbox" class="admin-user-check" value="'+esc(u.id)+'" aria-label="Select '+esc(u.name)+'" '+(sent||u.thank_you_status==='pending'?'disabled':'')+'></td><td>'+esc(u.name)+'</td><td>'+(u.username?'@'+esc(u.username):'—')+'</td><td>'+esc(u.email)+'</td><td>'+(u.created_at?new Date(u.created_at).toLocaleDateString():'—')+'</td><td><span class="admin-status '+(u.email_confirmed?'confirmed':'pending')+'">'+(u.email_confirmed?'Verified':'Unverified')+'</span></td><td><span class="admin-status '+(sent?'confirmed':'pending')+'">'+esc(status)+'</span></td></tr>';}).join(''):'<tr><td colspan="7">No accounts in this view.</td></tr>';$('#adminSelectAll').checked=false;}
async function loadAdminUsers(){const body=$('#adminUserRows');loadAdminAnalytics();body.innerHTML='<tr><td colspan="7">Loading account directory…</td></tr>';try{const data=await api('/admin/users');adminUsers=data.users||[];if(!data.email_configured)$('#adminMailStatus').textContent='Email is not configured yet. Add RESEND_API_KEY and EMAIL_FROM in Render to activate sending.';else $('#adminMailStatus').textContent='Email sender is configured. New recipients are ready to receive the thank-you message.';$('#adminUserCount').textContent=adminUsers.length;$('#adminConfirmedCount').textContent=adminUsers.filter(u=>u.email_confirmed).length;renderAdminUsers();}catch(e){body.innerHTML='<tr><td colspan="7">'+esc(e.message)+'</td></tr>';}}
async function loadAdminAnalytics(){try{const x=await api('/admin/analytics');$('#adminActiveToday').textContent=x.activeToday;$('#adminActiveWeek').textContent=x.activeWeek;$('#adminActiveMonth').textContent=x.activeMonth;$('#adminLoginCount').textContent=x.loginsToday;$('#adminTopStreak').textContent=x.topCurrent+' days';$('#adminBestStreak').textContent=x.bestStreak+' days';}catch(e){['adminActiveToday','adminActiveWeek','adminActiveMonth','adminLoginCount','adminTopStreak','adminBestStreak'].forEach(id=>$('#'+id).textContent='—');console.warn('Admin analytics unavailable:',e.message)}}
$('#refreshAdmin').onclick=loadAdminUsers;
$('#adminMailFilter').onchange=renderAdminUsers;$('#adminSelectAll').onchange=()=>$('.admin-user-check:not(:disabled)').forEach(c=>c.checked=$('#adminSelectAll').checked);
async function sendAdminMail(all){const ids=$('.admin-user-check:checked').map(x=>x.value);const newCount=adminUsers.filter(u=>u.email&&u.thank_you_status!=='sent'&&u.id!==authUser?.id).length;if(!all&&!ids.length){$('#adminMailStatus').textContent='Select at least one account that has not received the message.';return}if(!confirm(all?'Send the thank-you message to '+newCount+' accounts that have not received it yet? Already-sent accounts will be skipped.':`Send the thank-you message to ${ids.length} selected new account(s)?`))return;const status=$('#adminMailStatus');status.textContent='Sending…';try{const result=await api('/admin/thank-you',{method:'POST',body:JSON.stringify({all,userIds:all?undefined:ids,subject:$('#adminMailSubject').value,message:$('#adminMailMessage').value})});status.textContent=`Sent: ${result.sent}. Failed: ${result.failed}. Already sent: ${result.skippedAlreadySent}. Pending status checks: ${result.pending}.`;await loadAdminUsers();}catch(e){status.textContent=e.message;}}
$('#adminMailForm').onsubmit=e=>{e.preventDefault();sendAdminMail(false)};$('#adminMailAll').onclick=()=>sendAdminMail(true);
